from audit_utils import *

for tree,layer in [('fr_printed','French as printed'),('fr','French corrected')]:
 rel=f'sources/{tree}/fr/212.tex'
 def r(a,b,line,kind='reading',why='',count=1):
  replace(rel,a,b,layer,'212-109',line,'4.1; 4.2; nerve recurrence','400-dpi full scan and all three enlarged bands. '+why,kind,count=count)
 r('i.e.','i. e.','opening and final paragraphs',count=2,why='The abbreviation has a printed space.')
 r('qui transforment des sommes amalgamées en produits\nfibrés.',r'\uline{qui transforment des sommes amalgamées en produits fibrés}.','last clause of Proposition 4.1',why='The entire condition is straight-underlined, excluding the period.')
 r('« à un isomorphisme près »',r'\fquote{à un isomorphisme près}','paragraph before Corollary 4.2',why='The print has ordinary double quotes.')
 r('implique alors:', 'implique alors :','corollary introduction',why='A space precedes the colon.')
 r(r'\mathcal S$:',r'\mathcal S$ :','operation list introduction',why='A space precedes the colon.')
 r(r"\emph{pré-relation d'équivalence}",r"\uline{pré-relation d'équivalence}",'final definition',why='The defined phrase is straight-underlined.')
 r(r'\times_X(R,p_1),',r'\times_X(R,p_1)','recurrence display end',why='The display has no terminal comma.')
 r(r'\leq',r'\leqslant','projection-index range',count=2,why='Both inequalities have slanted lower strokes.')
 if tree=='fr_printed':
  r(r'p_{n-1}^{(n-1)})\times_X',r'p_n^{(n-1)})\times_X','recurrence, last-vertex projection',why='The scan prints subscript n, not n-1, beneath the superscript (n-1). The supplied transcription silently corrected this third index slip.')
 else:
  # Record retained, independently verified corrections without a needless
  # restore-and-reapply mutation of the already-correct text.
  with (ROOT/'CORRECTIONS.tsv').open('a',newline='') as ledger:
   out=csv.writer(ledger,delimiter='\t')
   for old,new,loc,sid,why in [
    (r'$(n+1)$-ième',r'$n$-ième','nerve-description sentence','FGA-CANON-ERR-0001','Confirmed existing correction: an n-simplex is a composable chain with n arrows, as obtained from Hom of the ordered category [0,n].'),
    (r'K_0=R',r'K_0=X','recurrence initial value','FGA-CANON-ERR-0001','Confirmed existing correction: functors from the one-object identity category select objects, so the zero component is X, whereas the first component is R.'),
    (r'p_n^{(n-1)}',r'p_{n-1}^{(n-1)}','recurrence, last-vertex projection','212-4-nerve-projection','Confirmed previously unmarked correction: K_(n-1) has vertices numbered 0 through n-1, precisely the range printed immediately below. The last target projection is p_(n-1)^(n-1); p_n^(n-1) is undefined.')]:
    out.writerow([rel,layer,'212-109',loc,sid,old,new,'Scan leaf 12, enlarged middle band: '+why,'misprint of the original','low'])
 s,_,_=page_text(rel,109)
 for old,new in [(r'\mathcal C',r'\text{\uwave{C}}'),(r'\mathcal S',r'\text{\uwave{S}}')]:
  r(old,new,'category alphabet',count=s.count(old),why='The category letters have wavy underlines.')
 upright_page(rel,layer,'212-109')

event('212-4.1','independent re-proof','Groupoid half: restrict K to increasing maps and use the category reconstruction on p. 108. The transposition of [0,1] gives an arrow reversal. The maps [0,2] to [0,1] with vertex sequences (0,1,0) and (1,0,1) force the two composites with this reversal to be the relevant identities. Hence the reconstructed category is a groupoid. The Segal bijections determine all higher components and all operations from arrows, compositions and inverses, so the full S-functor is its chaotic-category nerve; natural maps are precisely functors. Conversely that nerve sends every pushout A amalg_C B of nonempty finite sets to a pullback: choose c0 in C. A functor from a chaotic category to a groupoid is determined by its vertex objects and the isomorphisms from the object at c0. Two such functors agreeing on C have equal anchored isomorphisms for each identified vertex, so those data descend uniquely to the set pushout. This proves the full, unrestricted amalgamation condition, not just the chain concatenations.','212, pp. 108–109, Proposition 4.1, groupoid half')
event('212-4.2','targeted proof check','For each T, Hom(T,-) preserves the fibre products used in the nerve and the Segal comparisons. Apply the set-level reconstruction and equations of 4.1 to those point sets. The resulting source, target, identity, composition and inverse operations are natural in T, hence represented by Yoneda; equality and invertibility of the Segal comparisons are likewise detected on all T-points. Conversely the finite iterated fibre products of an internal category or groupoid construct each nerve component. Thus fibre products suffice; no terminal object of C is needed because the chosen object of objects supplies the base.','212, p. 109, Corollary 4.2')
event('FGA-CANON-ERR-0001','targeted proof check','Confirmed the linked existing corrections against the image and the nerve definition: the print reads (n+1)-ieme and K0=R; Hom([0,0],Z) is the object set X and Hom([0,n],Z) is a composable n-tuple of arrows. With K0=X and p0^(0)=id_X, the corrected recurrence gives K1=R and then the expected chains. The edition record was treated as a claim to check, not as authority. Its existing explanatory footnote remains an editorial annotation in the corrected layer only; it is not an original printed footnote.','212, p. 109, paragraph and display after Corollary 4.2')
event('212-4-nerve-projection','targeted proof check','The printed recurrence uses p_n^(n-1), but the subsequent line defines p_i^(n-1) only for 0 at most i at most n-1. The needed map is the final-vertex projection of a chain of n-1 arrows, namely p_(n-1)^(n-1); its fibre product with the source p1 of the added arrow imposes the correct composability condition. The supplied files already had n-1 without recording this additional original misprint. Restored n in the printed layer and explicitly recorded n-1 in the corrected layer.','212, p. 109, recurrence and following index range')
event('212-4-source-fibre-power','refuted, with the refined statement\'s id','Refined statement id: 212-4-nerve-projection. Even after replacing n+1 by n, a literal n-fold power of the single object (R,p1) over X is not the ordinary category nerve: in the category 0 to 1, R has three arrows, the common-source square has 2 squared plus 1 squared = 5 elements, while the composable-pair set has four. The recurrence, with the last-target projection and corrected initial value, is the precise valid construction. For a groupoid common-source tuples can be converted to composable chains using inverses, but that does not justify the prose for arbitrary categories. Retained the historical abbreviated fibre-power wording; this broader caveat belongs in the notes, not in an invented replacement sentence.','212, p. 109, phrase puissance fibree de (R,p1) sur X')
event('212-4-pre-equivalence','targeted proof check','A groupoid on object set X contains more data than its two maps R to X. For X a point and R a four-element set, the cyclic group of order four and the Klein four group supply nonisomorphic groupoid structures with identical source and target maps. Their coequalizer problem nevertheless uses only those maps, exactly as stated. The five listed operations generate all nerve maps by taking composable subchains, inserting identities and reversing arrows; in the category case only the first four operations are used. The printed face 0 and face 1 name the two vertices, not the modern omitted-vertex numbering convention.','212, p. 109, simplicial operations and final paragraph')
record_page('212',109,r'''Compared sources/fr_printed/fr/212.tex entry lines 462–510 and sources/fr/fr/212.tex entry lines 462–513 with scan leaf 12 at 400 dpi, full page and all three enlarged bands. Checked every superscript and subscript in the recurrence and its index range, all face names, the two displays, Corollary 4.2 and the definition of a pré-relation.

Both layers restore the underlined exactness condition and definition, quotes, spaced abbreviation and colons, unpunctuated recurrence, slanted inequalities, wavy category letters and upright mathematics. Confirmed FGA-CANON-ERR-0001: the printed (n+1)-ième and K_0=R remain in the printed layer; n-ième and K_0=X remain in the corrected layer. Its existing explanatory correction footnote remains only in the corrected layer and is expressly editorial. A further printed subscript n, already silently changed in the supplied sources, is now restored in the printed recurrence and recorded as n-1 in the corrected layer.

Completed an independent proof of Proposition 4.1 including all nonempty finite-set pushouts, and checked Corollary 4.2 by Yoneda. A separate explicit finite-category count shows why the prose about a common-source fibre power is too broad for arbitrary categories; the valid composable-chain construction is the recurrence. This caveat is recorded for the later notes without rewriting the historical sentence.''')
